	// 2. Use 5s for all 5 exponents (each 5 uses one 5)
	// 3. For 2s and 3s, decompose optimally
	//
	// For 2s and 3s:
	// - 2! = 2^1
	// - 3! = 2^1 * 3^1
	// - 4! = 2^3 * 3^1
	// - 6! = 2^4 * 3^2
	// - 8! = 2^7 * 3^2
	// - 9! = 2^7 * 3^4
	//
