	//
	// So the decomposition rules are:
	// - 4 = 3, 2, 2 (since 4! = 3! * 2! * 2!)
	// - 6 = 5, 3 (since 6! = 5! * 3!)
	// - 8 = 7, 2, 2, 2 (since 8! = 7! * 2! * 2! * 2!)
	// - 9 = 7, 3, 3, 2 (since 9! = 7! * 3! * 3! * 2!)
	//   Wait, let me check: 9! = 362880
