	// 
	// So we get: 5, 5, 5
	// Sorted: 555
	// 
	// Check: 5! * 5! * 5! = 120^3 = 1728000. Correct!

	// So the algorithm is:
	// 1. For each digit in input, decompose it using the rules above
	// 2. Collect all resulting digits
	// 3. Sort in descending order
	// 4. Output

	decomposition := map[int][]int{
